class Solution {
    long long ways(long long n) { return n < 0 ? 0 : (n + 1) * (n + 2) / 2; }
public:
    long long distributeCandies(int n, int limit) {
        long long ans = 0;
        for (int j = 0; j <= 3; ++j) {
            long long choose = (j == 0 || j == 3) ? 1 : 3;
            ans += (j % 2 ? -1 : 1) * choose * ways((long long)n - (long long)j * (limit + 1));
        }
        return ans;
    }
};
